{"path":"Standingwaves.html","old_str":"function radial(n,l,r){
  /* analytic hydrogen radial factor R_{nl}(r), in Bohr units */
  const rho = 2*r / n;
  const k = n - 1 - l;
  /* associated Laguerre L_k^{2l+1}(rho) via three-term recurrence in k */
  let L0 = 1, L1 = (2*l + 2 - rho);
  if(k === 0) return Math.pow(rho, l) * Math.exp(-rho/2);
  for(let i=1;i<k;i++){
    const L2 = ((2*i + 2*l + 1)*rho - (i + 1)) * L1 - (i + 2*l + 1)*(i + 1)*L0;
    L0 = L1; L1 = L2 / (i + 2);
  }
  const Lk = L1 / k;
  return Math.pow(rho, l) * Lk * Math.exp(-rho/2);
}","new_str":"function radial(n,l,r){
  /* analytic hydrogen radial factor R_{nl}(r), in Bohr units */
  const rho = 2*r / n;
  const k = n - 1 - l;
  /* associated Laguerre L_k^{α}(x), α = 2ℓ+1, via the three-term recurrence
     (i+1)² L_{i+1} = (2i+1+α−x) L_i − (i+α) L_{i−1}            */
  const alpha = 2*l + 1;
  let Lm1 = 1, L0 = 1 + alpha - rho;
  let L1 = L0;
  if(k === 0) L1 = Lm1;
  else if(k === 1) L1 = L0;
  else for(let i=1; i<k; i++){
    L1 = ((2*i + 1 + alpha - rho)*L0 - (i + alpha)*Lm1) / ((i + 1)*(i + 1));
    Lm1 = L0; L0 = L1;
  }
  return Math.pow(rho, l) * L1 * Math.exp(-rho/2);
}"}

